// Prints the layout of the NVIDIA encoder (NVENC) structures the engine uses, as Go constants: engine/nvenc_layout.go.
// The engine calls the driver without cgo, so sizes, field offsets and bit positions come from NVIDIA's own header:
//
//   git clone --depth 1 --branch n12.0.16.2 https://github.com/FFmpeg/nv-codec-headers
//   gcc -w -I nv-codec-headers/include/ffnvcodec -o nvlayout nvlayout.c && ./nvlayout | gofmt > ../../nvenc_layout.go
//
// API 12.0 (drivers 522.25 and newer, October 2022): newer drivers accept older versions, older drivers refuse newer ones.
// The structures hold only fixed-size fields and pointers, so a 64-bit Linux build of this tool gives the Windows layout.
#include <stdio.h>
#include <stddef.h>
#include <string.h>
#include <stdint.h>
#include "nvEncodeAPI.h"
#define SZ(T) printf("\tsz_%s = %zu\n", #T, sizeof(T))
#define OFF(T, f) printf("\to_%s_%s = %zu\n", #T, #f, offsetof(T, f))
// where a bit field sits: byte offset of its 32-bit word and its mask
#define BIT(T, f) do { T v; memset(&v, 0, sizeof v); v.f = ~0u; const unsigned char *p = (const unsigned char *)&v; size_t i = 0; while (i < sizeof v && !p[i]) i++; size_t w = i & ~(size_t)3; uint32_t m; memcpy(&m, p + w, 4); printf("\tb_%s_%s_off, b_%s_%s_mask = %zu, 0x%x\n", #T, #f, #T, #f, w, m); } while (0)
#define GUIDC(name, g) printf("\tguid_%s = [16]byte{0x%02x,0x%02x,0x%02x,0x%02x, 0x%02x,0x%02x, 0x%02x,0x%02x, 0x%02x,0x%02x,0x%02x,0x%02x,0x%02x,0x%02x,0x%02x,0x%02x}\n", name, (g).Data1 & 255, ((g).Data1 >> 8) & 255, ((g).Data1 >> 16) & 255, ((g).Data1 >> 24) & 255, (g).Data2 & 255, (g).Data2 >> 8, (g).Data3 & 255, (g).Data3 >> 8, (g).Data4[0], (g).Data4[1], (g).Data4[2], (g).Data4[3], (g).Data4[4], (g).Data4[5], (g).Data4[6], (g).Data4[7])
