  printf("// Code generated by engine/tools/nvlayout (nv-codec-headers n12.0.16.2, NVENC API %d.%d). DO NOT EDIT.\n\npackage main\n\nconst (\n", NVENCAPI_MAJOR_VERSION, NVENCAPI_MINOR_VERSION);
