  printf("\tver_FUNCTION_LIST = 0x%x\n", (unsigned)NV_ENCODE_API_FUNCTION_LIST_VER);
  printf("\tver_OPEN_SESSION_EX = 0x%x\n", (unsigned)NV_ENC_OPEN_ENCODE_SESSION_EX_PARAMS_VER);
  printf("\tver_INITIALIZE_PARAMS = 0x%x\n", (unsigned)NV_ENC_INITIALIZE_PARAMS_VER);
  printf("\tver_CONFIG = 0x%x\n", (unsigned)NV_ENC_CONFIG_VER);
  printf("\tver_PRESET_CONFIG = 0x%x\n", (unsigned)NV_ENC_PRESET_CONFIG_VER);
  printf("\tver_RC_PARAMS = 0x%x\n", (unsigned)NV_ENC_RC_PARAMS_VER);
  printf("\tver_CREATE_INPUT_BUFFER = 0x%x\n", (unsigned)NV_ENC_CREATE_INPUT_BUFFER_VER);
  printf("\tver_CREATE_BITSTREAM_BUFFER = 0x%x\n", (unsigned)NV_ENC_CREATE_BITSTREAM_BUFFER_VER);
  printf("\tver_LOCK_INPUT_BUFFER = 0x%x\n", (unsigned)NV_ENC_LOCK_INPUT_BUFFER_VER);
  printf("\tver_LOCK_BITSTREAM = 0x%x\n", (unsigned)NV_ENC_LOCK_BITSTREAM_VER);
  printf("\tver_PIC_PARAMS = 0x%x\n", (unsigned)NV_ENC_PIC_PARAMS_VER);
  printf("\tver_CAPS_PARAM = 0x%x\n", (unsigned)NV_ENC_CAPS_PARAM_VER);
