  OFF(NV_ENCODE_API_FUNCTION_LIST, version);
  OFF(NV_ENCODE_API_FUNCTION_LIST, nvEncOpenEncodeSession);
  OFF(NV_ENCODE_API_FUNCTION_LIST, nvEncGetEncodeCaps);
