  printf("\n");
  SZ(NV_ENC_OPEN_ENCODE_SESSION_EX_PARAMS);
  OFF(NV_ENC_OPEN_ENCODE_SESSION_EX_PARAMS, version); OFF(NV_ENC_OPEN_ENCODE_SESSION_EX_PARAMS, deviceType); OFF(NV_ENC_OPEN_ENCODE_SESSION_EX_PARAMS, device); OFF(NV_ENC_OPEN_ENCODE_SESSION_EX_PARAMS, apiVersion);
  printf("\n");
  SZ(NV_ENC_CAPS_PARAM); OFF(NV_ENC_CAPS_PARAM, version); OFF(NV_ENC_CAPS_PARAM, capsToQuery);
