  SZ(NV_ENC_PRESET_CONFIG); OFF(NV_ENC_PRESET_CONFIG, version); OFF(NV_ENC_PRESET_CONFIG, presetCfg);
  printf("\n");
  SZ(NV_ENC_CONFIG);
  OFF(NV_ENC_CONFIG, version); OFF(NV_ENC_CONFIG, profileGUID); OFF(NV_ENC_CONFIG, gopLength); OFF(NV_ENC_CONFIG, frameIntervalP); OFF(NV_ENC_CONFIG, frameFieldMode); OFF(NV_ENC_CONFIG, mvPrecision); OFF(NV_ENC_CONFIG, rcParams); OFF(NV_ENC_CONFIG, encodeCodecConfig);
  printf("\n");
  SZ(NV_ENC_RC_PARAMS);
  OFF(NV_ENC_RC_PARAMS, version); OFF(NV_ENC_RC_PARAMS, rateControlMode); OFF(NV_ENC_RC_PARAMS, constQP); OFF(NV_ENC_RC_PARAMS, averageBitRate); OFF(NV_ENC_RC_PARAMS, maxBitRate); OFF(NV_ENC_RC_PARAMS, vbvBufferSize); OFF(NV_ENC_RC_PARAMS, vbvInitialDelay);
  BIT(NV_ENC_RC_PARAMS, enableAQ); BIT(NV_ENC_RC_PARAMS, enableLookahead); BIT(NV_ENC_RC_PARAMS, disableIadapt); BIT(NV_ENC_RC_PARAMS, disableBadapt); BIT(NV_ENC_RC_PARAMS, enableTemporalAQ); BIT(NV_ENC_RC_PARAMS, zeroReorderDelay); BIT(NV_ENC_RC_PARAMS, strictGOPTarget); BIT(NV_ENC_RC_PARAMS, aqStrength);
  OFF(NV_ENC_RC_PARAMS, lookaheadDepth); OFF(NV_ENC_RC_PARAMS, lowDelayKeyFrameScale); OFF(NV_ENC_RC_PARAMS, multiPass);
  printf("\n");
  SZ(NV_ENC_CONFIG_H264);
  BIT(NV_ENC_CONFIG_H264, enableTemporalSVC); BIT(NV_ENC_CONFIG_H264, outputAUD); BIT(NV_ENC_CONFIG_H264, disableSPSPPS); BIT(NV_ENC_CONFIG_H264, outputBufferingPeriodSEI); BIT(NV_ENC_CONFIG_H264, outputPictureTimingSEI); BIT(NV_ENC_CONFIG_H264, repeatSPSPPS); BIT(NV_ENC_CONFIG_H264, enableIntraRefresh); BIT(NV_ENC_CONFIG_H264, enableFillerDataInsertion);
  OFF(NV_ENC_CONFIG_H264, level); OFF(NV_ENC_CONFIG_H264, idrPeriod); OFF(NV_ENC_CONFIG_H264, separateColourPlaneFlag); OFF(NV_ENC_CONFIG_H264, adaptiveTransformMode); OFF(NV_ENC_CONFIG_H264, entropyCodingMode); OFF(NV_ENC_CONFIG_H264, sliceMode); OFF(NV_ENC_CONFIG_H264, sliceModeData); OFF(NV_ENC_CONFIG_H264, h264VUIParameters); OFF(NV_ENC_CONFIG_H264, chromaFormatIDC); OFF(NV_ENC_CONFIG_H264, maxNumRefFrames); OFF(NV_ENC_CONFIG_H264, useBFramesAsRef); OFF(NV_ENC_CONFIG_H264, numRefL0);
  printf("\n");
  SZ(NV_ENC_CONFIG_H264_VUI_PARAMETERS);
  OFF(NV_ENC_CONFIG_H264_VUI_PARAMETERS, overscanInfoPresentFlag); OFF(NV_ENC_CONFIG_H264_VUI_PARAMETERS, videoSignalTypePresentFlag); OFF(NV_ENC_CONFIG_H264_VUI_PARAMETERS, videoFormat); OFF(NV_ENC_CONFIG_H264_VUI_PARAMETERS, videoFullRangeFlag); OFF(NV_ENC_CONFIG_H264_VUI_PARAMETERS, colourDescriptionPresentFlag); OFF(NV_ENC_CONFIG_H264_VUI_PARAMETERS, colourPrimaries); OFF(NV_ENC_CONFIG_H264_VUI_PARAMETERS, transferCharacteristics); OFF(NV_ENC_CONFIG_H264_VUI_PARAMETERS, colourMatrix);
  printf("\n");
  SZ(NV_ENC_INITIALIZE_PARAMS);
  OFF(NV_ENC_INITIALIZE_PARAMS, version); OFF(NV_ENC_INITIALIZE_PARAMS, encodeGUID); OFF(NV_ENC_INITIALIZE_PARAMS, presetGUID); OFF(NV_ENC_INITIALIZE_PARAMS, encodeWidth); OFF(NV_ENC_INITIALIZE_PARAMS, encodeHeight); OFF(NV_ENC_INITIALIZE_PARAMS, darWidth); OFF(NV_ENC_INITIALIZE_PARAMS, darHeight); OFF(NV_ENC_INITIALIZE_PARAMS, frameRateNum); OFF(NV_ENC_INITIALIZE_PARAMS, frameRateDen); OFF(NV_ENC_INITIALIZE_PARAMS, enableEncodeAsync); OFF(NV_ENC_INITIALIZE_PARAMS, enablePTD);
  OFF(NV_ENC_INITIALIZE_PARAMS, encodeConfig); OFF(NV_ENC_INITIALIZE_PARAMS, maxEncodeWidth); OFF(NV_ENC_INITIALIZE_PARAMS, maxEncodeHeight); OFF(NV_ENC_INITIALIZE_PARAMS, tuningInfo); OFF(NV_ENC_INITIALIZE_PARAMS, bufferFormat);
  printf("\n");
  SZ(NV_ENC_CREATE_INPUT_BUFFER);
  OFF(NV_ENC_CREATE_INPUT_BUFFER, version); OFF(NV_ENC_CREATE_INPUT_BUFFER, width); OFF(NV_ENC_CREATE_INPUT_BUFFER, height); OFF(NV_ENC_CREATE_INPUT_BUFFER, memoryHeap); OFF(NV_ENC_CREATE_INPUT_BUFFER, bufferFmt); OFF(NV_ENC_CREATE_INPUT_BUFFER, inputBuffer);
  printf("\n");
  SZ(NV_ENC_CREATE_BITSTREAM_BUFFER);
  OFF(NV_ENC_CREATE_BITSTREAM_BUFFER, version); OFF(NV_ENC_CREATE_BITSTREAM_BUFFER, bitstreamBuffer);
  printf("\n");
  SZ(NV_ENC_LOCK_INPUT_BUFFER);
  OFF(NV_ENC_LOCK_INPUT_BUFFER, version); OFF(NV_ENC_LOCK_INPUT_BUFFER, inputBuffer); OFF(NV_ENC_LOCK_INPUT_BUFFER, bufferDataPtr); OFF(NV_ENC_LOCK_INPUT_BUFFER, pitch);
  printf("\n");
  SZ(NV_ENC_PIC_PARAMS);
  OFF(NV_ENC_PIC_PARAMS, version); OFF(NV_ENC_PIC_PARAMS, inputWidth); OFF(NV_ENC_PIC_PARAMS, inputHeight); OFF(NV_ENC_PIC_PARAMS, inputPitch); OFF(NV_ENC_PIC_PARAMS, encodePicFlags); OFF(NV_ENC_PIC_PARAMS, frameIdx); OFF(NV_ENC_PIC_PARAMS, inputTimeStamp); OFF(NV_ENC_PIC_PARAMS, inputDuration); OFF(NV_ENC_PIC_PARAMS, inputBuffer); OFF(NV_ENC_PIC_PARAMS, outputBitstream); OFF(NV_ENC_PIC_PARAMS, completionEvent); OFF(NV_ENC_PIC_PARAMS, bufferFmt); OFF(NV_ENC_PIC_PARAMS, pictureStruct); OFF(NV_ENC_PIC_PARAMS, pictureType); OFF(NV_ENC_PIC_PARAMS, codecPicParams);
  printf("\n");
  SZ(NV_ENC_LOCK_BITSTREAM);
  OFF(NV_ENC_LOCK_BITSTREAM, version); BIT(NV_ENC_LOCK_BITSTREAM, doNotWait); OFF(NV_ENC_LOCK_BITSTREAM, outputBitstream); OFF(NV_ENC_LOCK_BITSTREAM, frameIdx); OFF(NV_ENC_LOCK_BITSTREAM, bitstreamSizeInBytes); OFF(NV_ENC_LOCK_BITSTREAM, outputTimeStamp); OFF(NV_ENC_LOCK_BITSTREAM, bitstreamBufferPtr); OFF(NV_ENC_LOCK_BITSTREAM, pictureType);
  printf("\n\t// values\n");
